"""Automatic invite consumes an actual loopback inbox message; no real bank/FNS activity."""
import json,secrets,subprocess,requests
import test_owner_workflow as workflow
class AutomaticPaidAccess(workflow.OwnerWorkflow):
 @classmethod
 def setUpClass(cls):
  super().setUpClass();r=subprocess.run([cls.f.php,str(cls.f.path/'scripts/migrate-access.php'),'up'],capture_output=True,text=True)
  if r.returncode:raise RuntimeError(r.stderr)
 def job(self,oid):return self.wget('access&order='+str(oid)).json()['job']
 def pump(self):return self.f.php_eval('require $v["root"]."/private/app.php";require $v["root"]."/private/lifecycle/routes.php";require $v["root"]."/private/lifecycle/access.php";echo json_encode(["processed"=>la_pump(10)]);',{'root':str(self.f.path)})
 def prepared(self,open_portal=True):
  oid,legacy,g,values,terms=self.new_documents();docs=[]
  for t in self.templates[:2]:
   b=self.must(self.gen(t,terms))['record'];p=self.lg('documents/'+str(b['id'])).json()['record']['pdf'];self.must(self.ctp('review-pdf',binding_id=int(b['id']),pdf_checksum=p['checksum'],confirm=True,reason='SYNTHETIC actual PDF inspected'));docs.append(b)
  self.paper_docs=[legacy[0],*docs];link=self.create_link(oid,docs,False);self.assertEqual(link.status_code,200,link.text);g,x=self.exchange(link.json()['url'].split('#token=')[1]);self.consent(g,x)
  for b in docs:
   r=g.post(self.base+'/prospect-api.php?r=upload',data={'binding_id':b['id'],'request_key':secrets.token_hex(32)},files={'file':('SYNTHETIC-paper-copy-not-real-signature.pdf',self.pdf(),'application/pdf')});self.assertEqual(r.status_code,200,r.text);self.must(self.own('import',upload_id=r.json()['id'],confirm=True,reason='SYNTHETIC test copy imported'));fresh=self.lg('documents/'+str(b['id'])).json()['record'];self.must(self.action(fresh,'verify'))
   r=self.owner.post(self.base+'/api.php?r=crm/collab/upload',data={'project_id':str(self.project_id),'request_key':secrets.token_hex(32),'visibility':'customer'},files={'file':('SYNTHETIC-completed-copy.pdf',self.pdf(),'application/pdf')});fid=int(self.must(r)['file']['id']);self.must(self.ctp('completed-copy',binding_id=int(b['id']),file_id=fid,confirm=True,reason='SYNTHETIC full paper-copy test review, not legal validation'))
  t=self.approved_template('invoice');self.must(self.ctp('release-payment',binding_id=int(docs[0]['id']),invoice_template_id=int(t['id']),confirm=True,reason='SYNTHETIC original schedule checked'))
  if open_portal:self.setup_action('open',confirm=True)
  items=sorted([i for i in self.lg('finance').json()['items'] if int(i['order_id'])==oid],key=lambda i:int(i['id']));self.smtp.messages.clear();return oid,items,docs
 def test_automatic_payment_invite_received_activation_replay_and_authorized_delivery(self):
  oid,items,docs=self.prepared();item=items[0];key=secrets.token_hex(32);entry='SYNTHETIC-'+secrets.token_hex(12);r=self.bank(item,bank_entry_id=entry,request_key=key);self.assertEqual(r.status_code,200,r.text);self.assertEqual(r.json()['access']['state'],'SMTP_ACCEPTED');self.assertEqual(len(self.smtp.messages),1);self.assertFalse(self.job(oid)['delivery_confirmed']);self.assertEqual(self.bank(item,bank_entry_id=entry,request_key=key).status_code,200);self.assertEqual(self.bank(item,bank_entry_id=entry).status_code,409);self.pump();self.assertEqual(len(self.smtp.messages),1);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_customer_accounts WHERE customer_id=?',params=[self.customer_id])[0]['n'],1)
  token=self.token();self.assertNotIn(token,json.dumps(self.f.sql('SELECT * FROM nd_lc_access_jobs')));s=requests.Session();r=s.get(self.base+'/customer-api.php?r=session');s.headers['X-CSRF-Token']=r.json()['csrf'];payload={'token':token,'password':'SYNTHETIC-auto12345','password_confirmation':'SYNTHETIC-auto12345','consent':True,'policy_version':self.policy['version']};self.assertEqual(s.post(self.base+'/customer-api.php?r=invite',json=payload).status_code,200);self.assertEqual(s.post(self.base+'/customer-api.php?r=invite',json=payload).status_code,422);r=s.post(self.base+'/customer-api.php?r=login',json={'email':self.invite_email,'password':'SYNTHETIC-auto12345'});self.assertEqual(r.status_code,200,r.text);s.headers['X-CSRF-Token']=r.json()['csrf'];self.assertTrue(self.job(oid)['delivery_confirmed']);self.assertEqual(self.job(oid)['state'],'ACTIVATED');self.assertEqual(self.fg(oid,s).status_code,200);self.assertNotEqual(self.fg(oid,self.stranger).status_code,200)
  self.material_ready(oid);self.must(self.fp(oid,'start-production'));stage=self.stage();v=self.must(self.fp(oid,'milestones',**self.evidence(stage)))['id'];record=self.f.sql('SELECT version,checksum FROM nd_lc_milestone_versions WHERE id=?',params=[v])[0];self.must(self.fp(oid,'milestones/'+str(v)+'/respond',s,version=int(record['version']),checksum=record['checksum'],kind='ACCEPT',feedback='SYNTHETIC reviewed delivered test result'));self.assertEqual(self.fg(oid).json()['record']['milestones'][-1]['state'],'ACCEPTED');self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_lc_receipt_evidence')[0]['n'],0)
 def test_blocked_gates_then_smtp_failure_retry_expiry_and_audited_fallback(self):
  oid,items,docs=self.prepared(False);item=items[0];self.assertEqual(self.bank(item).status_code,200);self.assertEqual(self.job(oid)['blocked_code'],'portal_closed');self.assertEqual(len(self.smtp.messages),0);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_customer_accounts WHERE customer_id=?',params=[self.customer_id])[0]['n'],0)
  self.setup_action('open',confirm=True);self.smtp.reject=True;self.f.sql('UPDATE nd_lc_access_jobs SET next_attempt=UTC_TIMESTAMP() WHERE order_id=?',params=[oid]);self.pump();self.assertEqual(self.job(oid)['state'],'FAILED');self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_customer_tokens t JOIN nd_customer_accounts a ON a.id=t.account_id WHERE a.customer_id=? AND t.used_at IS NULL',params=[self.customer_id])[0]['n'],0)
  self.smtp.reject=False;self.f.sql('UPDATE nd_lc_access_jobs SET next_attempt=UTC_TIMESTAMP() WHERE order_id=?',params=[oid]);self.pump();self.assertEqual(self.job(oid)['state'],'SMTP_ACCEPTED');self.assertEqual(len(self.smtp.messages),1);token=self.token();self.f.sql('UPDATE nd_customer_tokens SET expires_at=0 WHERE token_hash=SHA2(?,256)',params=[token]);self.f.sql('UPDATE nd_lc_access_jobs SET next_attempt=UTC_TIMESTAMP() WHERE order_id=?',params=[oid]);self.pump();j=self.job(oid);self.assertEqual(j['state'],'EXPIRED');r=self.owner.post(self.base+'/order-workflow-api.php?r=access/retry',json={'order_id':oid,'version':int(j['version']),'request_key':secrets.token_hex(32),'confirm':True,'reason':'SYNTHETIC owner reviewed expiry and authorized replacement'});self.assertEqual(r.status_code,200,r.text);self.assertEqual(r.json()['job']['state'],'SMTP_ACCEPTED');self.assertEqual(len(self.smtp.messages),2);self.assertNotEqual(self.token(),token);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_customer_accounts WHERE customer_id=?',params=[self.customer_id])[0]['n'],1)
 def test_uncertain_smtp_never_retransmits_and_received_link_stays_valid(self):
  oid,items,docs=self.prepared();self.smtp.drop_after_data=True;self.addCleanup(setattr,self.smtp,'drop_after_data',False)
  r=self.bank(items[0]);self.assertEqual(r.status_code,200,r.text);self.assertEqual(self.job(oid)['state'],'UNCERTAIN');self.assertEqual(len(self.smtp.messages),1)
  self.f.sql('UPDATE nd_lc_access_jobs SET next_attempt=UTC_TIMESTAMP() WHERE order_id=?',params=[oid]);self.pump();self.assertEqual(len(self.smtp.messages),1)
  token=self.token();s=requests.Session();r=s.get(self.base+'/customer-api.php?r=session');s.headers['X-CSRF-Token']=r.json()['csrf'];payload={'token':token,'password':'SYNTHETIC-auto12345','password_confirmation':'SYNTHETIC-auto12345','consent':True,'policy_version':self.policy['version']};self.assertEqual(s.post(self.base+'/customer-api.php?r=invite',json=payload).status_code,200);self.assertTrue(self.job(oid)['delivery_confirmed'])

for name in dir(workflow.OwnerWorkflow):
 if name.startswith('test_'):setattr(AutomaticPaidAccess,name,None)
